<?php
namespace App\Filament\Resources;use App\Filament\Resources\PurifierBrandResource\Pages;use Filament\Resources\Forms\Components;use Filament\Resources\Forms\Form;use Filament\Resources\Resource;use Filament\Resources\Tables\Columns;use Filament\Resources\Tables\Table;
class PurifierBrandResource extends Resource{public static $label='Hãng máy lọc';public static function navigationItems(){return [];}public static function form(Form $f){return$f->schema([Components\TextInput::make('name')->label('Tên')->required(),Components\TextInput::make('code')->label('Mã')->required()->unique(static::getModel(),'code',true),Components\Select::make('status')->label('Trạng thái')->options(['active'=>'Hoạt động','inactive'=>'Ngừng'])->default('active')]);}public static function table(Table $t){return$t->columns([Columns\Text::make('code')->label('Mã')->primary(),Columns\Text::make('name')->label('Tên'),Columns\Text::make('status')->label('Trạng thái')]);}public static function routes(){return[Pages\ListPurifierBrands::routeTo('/','index'),Pages\CreatePurifierBrand::routeTo('/create','create'),Pages\EditPurifierBrand::routeTo('/{record}/edit','edit')];}}
